      "mainEntity": [
        {
          "@type": "Question",
          "name": "What's the difference between a custom facade and a customisable standard system?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "A custom facade is designed specifically for one building from the ground up, while a customisable standard system lets you choose options, colour, panel size, finish, within an existing, pre-developed product line."
          }
        },
        {
          "@type": "Question",
          "name": "Does a custom facade always cost more than a standard system?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Generally yes, since custom work requires dedicated design, engineering, and fabrication time specific to one project, rather than reusing an already developed and tested standard product across multiple buildings."
          }
        },
        {
          "@type": "Question",
          "name": "How do I know if my project actually needs a fully custom facade?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Fully custom work is worth its cost when your site conditions, brand identity, or design ambition genuinely can't be achieved within a standard system's constraints. Many projects achieve strong results through a standard system with thoughtful material combinations instead."
          }
        },
        {
          "@type": "Question",
          "name": "What should I ask a facade company claiming to offer custom design?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Ask specifically whether they're proposing a fully custom design built from your building's exact conditions, or a standard system with customisable options, since these are genuinely different and shouldn't be priced or evaluated the same way."
          }
        },
        {
          "@type": "Question",
          "name": "Can custom facade elements be combined with standard systems on one building?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Yes, this is a common and cost-effective approach, using a custom feature element, an entrance or a specific accent zone, alongside a more standard system across the rest of the building."
          }
        }
